"""UI 截图-判断-等待 工具函数。

从 ``autowsgr.ui.page`` 迁移而来，提供:

- **NavigationError** — 导航验证失败异常
- **NavConfig / DEFAULT_NAV_CONFIG** — 导航操作参数
- **wait_for_page / wait_leave_page** — 底层截图轮询
- **click_and_wait_for_page / click_and_wait_leave_page** — 带重试的一步导航
- **confirm_operation** — 确认弹窗点击

所有轮询入口都接受可选的 ``stop_event`` (``ctx.stop_event``)。用户点「停止」
后, 等待中的截图轮询会在 ``Event.wait`` 返回的瞬间抛
:class:`~autowsgr.infra.exceptions.TaskStopRequested`, 不再等满整个超时
(批次 4.7: 导航中断延迟 3.5s → <1s)。
"""

from __future__ import annotations

import threading
import time
from dataclasses import dataclass
from typing import TYPE_CHECKING

import numpy as np

from autowsgr.infra.exceptions import NavigationError, PageNotRecognizedError, TaskStopRequested
from autowsgr.infra.logger import get_logger
from autowsgr.vision import ImageChecker


if TYPE_CHECKING:
    from collections.abc import Callable

    import numpy as np

    from autowsgr.emulator import AndroidController


_log = get_logger('ui')

# 异常类统一由 infra.exceptions 提供（含 StuckError），此处仅 re-export，
# 避免出现两份 NavigationError 导致 `except NavigationError` 漏接。

# ---------------------------------------------------------------------------
# 导航配置
# ---------------------------------------------------------------------------


@dataclass(frozen=True, slots=True)
class NavConfig:
    """导航操作参数配置。

    Attributes
    ----------
    max_retries:
        点击重试最大次数 (含首次)。
    retry_delay:
        两次点击之间的等待 (秒)。
    timeout:
        每轮验证的超时 (秒)。
    interval:
        验证循环中两次截图的间隔 (秒)。
    stable_frames:
        判定「已到达」所需的连续匹配帧数，默认 2。
        只在 :func:`act_and_wait` 这类「点击后等结果」的路径生效；
        直接调用 :func:`wait_for_page` 时默认仍是 1 帧，保持原行为。
    stable_delay:
        两次确认之间的间隔 (秒)，默认 0.12。scrcpy 返回「最近一帧」，
        间隔过短两次会拿到同一张图，确认失效。

    Note
    ----
    2026-10-25 删除了 ``handle_overlays`` 字段。它此前只声明不实现
    (``wait_for_page`` / ``wait_leave_page`` 里都标注 ``# noqa: ARG001``),
    docstring 却承诺「自动处理游戏浮层」——属于文档说谎。浮层处理需要
    按浮层类型点各自的关闭按钮, 属于独立议题 (见风险清单 R46 遗留项),
    不宜用一个布尔开关假装已解决。
    """

    max_retries: int = 2
    retry_delay: float = 1.0
    timeout: float = 5.0
    interval: float = 0.5
    stable_frames: int = 2
    stable_delay: float = 0.12


DEFAULT_NAV_CONFIG = NavConfig()


# ---------------------------------------------------------------------------
# 停止信号
# ---------------------------------------------------------------------------


def _raise_if_stop_requested(stop_event: threading.Event | None, stage: str) -> None:
    """``stop_event`` 已置位时立即抛 :class:`TaskStopRequested`。

    放在**每轮截图之前**而不是之后, 是为了让「已经在等待时被停止」的场景
    一次截图都不用拍; 也让 ``except NavigationError`` 不会把用户主动停止
    误判成导航失败 (``TaskStopRequested`` 不是 ``NavigationError`` 子类)。
    """
    if stop_event is not None and stop_event.is_set():
        _log.info('[UI] 收到停止请求, 中断等待: {}', stage)
        raise TaskStopRequested(stage)


def _sleep_or_stop(
    stop_event: threading.Event | None,
    seconds: float,
    stage: str,
) -> None:
    """等待 ``seconds`` 秒, 但 ``stop_event`` 一置位就立即醒来。

    用 ``Event.wait`` 而不是 ``time.sleep`` 是延迟指标的关键: 停止按钮到
    循环醒来只差一次线程调度 (毫秒级), 不必等满整个 ``interval``。
    """
    if stop_event is None:
        time.sleep(seconds)
        return
    if stop_event.wait(seconds):
        _raise_if_stop_requested(stop_event, stage)


# ---------------------------------------------------------------------------
# 画面稳定（动画）轮询
# ---------------------------------------------------------------------------

_STABLE_SAMPLE_STEP = 8
"""帧差采样步长：每 8 像素取一点，既保留整屏变化又降低计算量。"""


def _frame_delta(previous: np.ndarray, current: np.ndarray) -> float:
    """返回两帧的采样平均绝对差 (0-255)，形状不一致视为完全变化。"""
    if previous.shape != current.shape:
        return float('inf')
    a = previous[::_STABLE_SAMPLE_STEP, ::_STABLE_SAMPLE_STEP]
    b = current[::_STABLE_SAMPLE_STEP, ::_STABLE_SAMPLE_STEP]
    diff = np.abs(a.astype(np.int16) - b.astype(np.int16))
    return float(diff.mean())


def wait_for_stable_screen(
    ctrl: AndroidController,
    *,
    timeout: float = 1.0,
    interval: float = 0.12,
    stable_frames: int = 2,
    max_diff: float = 2.0,
    source: str = '',
    stop_event: threading.Event | None = None,
) -> np.ndarray:
    """轮询截图，直到连续 ``stable_frames`` 帧画面差异不超过 ``max_diff``。

    替代「等动画就 ``time.sleep(1.5)``」的固定延迟：画面已经稳定时立即返回，
    仍在播放动画时继续等，超时则返回最后一帧（动画等待不应把任务判死）。

    判定依据是**帧差**而非页面签名：适用于"画面正在过渡、还没有明确目标页"
    的场景（决战地图进图、overlay 出现/消失、编队页加载）。有明确目标页时
    仍应优先用 :func:`click_and_wait_for_page` / :func:`act_and_wait`。

    Parameters
    ----------
    timeout:
        最长等待时间（秒）；超时返回最后一帧。
    interval:
        两次截图间隔（秒）。
    stable_frames:
        判定稳定所需的连续相似帧数（含第一帧），最小按 2 处理。
    max_diff:
        采样平均绝对差阈值（0-255）。默认 2.0 可容忍视频编码噪声。
    source:
        日志中的阶段名。
    stop_event:
        任务停止信号；置位即抛 :class:`TaskStopRequested`。
    """
    stage = f'等待画面稳定: {source or "?"}'
    required = max(2, stable_frames)
    deadline = time.monotonic() + max(timeout, 0.0)
    previous = ctrl.screenshot()
    stable = 1
    attempt = 1

    while stable < required:
        if time.monotonic() >= deadline:
            _log.debug(
                '[UI] 画面稳定等待超时: {} (超时 {:.1f}s, 连续相似 {} 帧)',
                stage,
                timeout,
                stable,
            )
            return previous
        _sleep_or_stop(stop_event, interval, stage)
        _raise_if_stop_requested(stop_event, stage)
        current = ctrl.screenshot()
        attempt += 1
        delta = _frame_delta(previous, current)
        if delta <= max_diff:
            stable += 1
        else:
            _log.debug(
                '[UI] 画面仍在变化: {} (第 {} 帧, 差 {:.2f})',
                stage,
                attempt,
                delta,
            )
            stable = 1
        previous = current

    _log.debug('[UI] 画面已稳定: {} ({} 帧, 超时 {:.1f}s)', stage, attempt, timeout)
    return previous


# ---------------------------------------------------------------------------
# 底层验证
# ---------------------------------------------------------------------------


def wait_for_page(
    ctrl: AndroidController,
    checker: Callable[[np.ndarray], bool],
    *,
    timeout: float = DEFAULT_NAV_CONFIG.timeout,
    interval: float = DEFAULT_NAV_CONFIG.interval,
    source: str = '',
    target: str = '',
    candidates: set[str] | None = None,
    stable_frames: int = 1,
    stable_delay: float = DEFAULT_NAV_CONFIG.stable_delay,
    capture_error: bool = True,
    stop_event: threading.Event | None = None,
) -> np.ndarray:
    """反复截图，直到 ``checker`` 连续 ``stable_frames`` 帧返回 ``True``。

    .. note::
       本文曾声称「内置浮层消除」，实际从未实现 (参数 ``handle_overlays``
       只声明不消费)。2026-10-25 移除该参数, 浮层处理另行立项。轮询期间
       若出现浮层挡住 checkers, 表现为超时, 日志会带上当前页与超时次数。

    Parameters
    ----------
    candidates:
        当前页识别的候选页面名集合 (来自 UIStack), 收缩轮询日志中
        全量识别的搜索空间;``None`` 时全量识别。
    stable_frames:
        判定到达所需的**连续匹配帧数**，默认 1 保持原行为。
        置 2 可挡掉转场渐变造成的假到达 (动画中间态恰好满足 checker)，
        代价是到达时多一次 ``stable_delay`` 的等待。只有「点击之后等结果」
        这类由 :func:`act_and_wait` 发起的等待才建议开启。
    stable_delay:
        两次确认之间的间隔 (秒)。不能取 0 —— scrcpy 返回的是「最近一帧」，
        间隔太短两次拿到同一张图，确认就失去意义。
    capture_error:
        超时时是否保存现场截图。内部重试的中间轮次传 ``False``，
        避免一次导航留下多张 1.7MB 的 NavError 截图。
    stop_event:
        任务停止信号 (``ctx.stop_event``)。轮询内用 ``Event.wait`` 等待
        ``interval``/``stable_delay``，置位即抛 :class:`TaskStopRequested`；
        ``None`` 时行为与旧版完全一致 (只按超时退出)。

    Raises
    ------
    NavigationError
        超时仍未匹配。
    TaskStopRequested
        等待期间 ``stop_event`` 被置位 (用户点「停止」)。
    """
    from autowsgr.ui.page import get_current_page

    stage = f'等待页面: {source or "?"} -> {target or "?"}'
    deadline = time.monotonic() + timeout
    attempt = 0
    _log.debug('[UI] 等待到达: {} -> {} (超时 {:.1f}s)', source or '?', target or '?', timeout)

    while True:
        # 停止优先于截图与超时判定：用户点了停止就直接退出，不再拍图。
        _raise_if_stop_requested(stop_event, stage)
        attempt += 1
        screen = ctrl.screenshot()

        if checker(screen):
            if stable_frames > 1:
                confirmed = True
                for _ in range(stable_frames - 1):
                    _sleep_or_stop(stop_event, stable_delay, stage)
                    recheck = ctrl.screenshot()
                    if not checker(recheck):
                        confirmed = False
                        break
                    screen = recheck
                if not confirmed:
                    _log.debug(
                        '[UI] 到达抖动, 继续等待: {} -> {} (第 {} 次截图)',
                        source or '?',
                        target or '?',
                        attempt,
                    )
                    _sleep_or_stop(stop_event, interval, stage)
                    continue
            _log.debug(
                '[UI] 已到达: {} -> {} (第 {} 次截图)', source or '?', target or '?', attempt
            )
            return screen

        current = get_current_page(screen, candidates=candidates)
        _log.debug(
            '[UI] 等待 #{}: {} -> {}, 当前={}',
            attempt,
            source or '?',
            target or '?',
            current or '未知',
        )

        _raise_if_stop_requested(stop_event, stage)

        if time.monotonic() >= deadline:
            msg = (
                f'等待超时: {source or "?"} -> {target or "?"}, '
                f'{attempt} 次截图后仍未到达, 当前: {current or "未知"}'
            )
            _log.error('[UI] {}', msg)
            raise NavigationError(msg, screen=screen if capture_error else None)

        _sleep_or_stop(stop_event, interval, stage)


def wait_leave_page(
    ctrl: AndroidController,
    checker: Callable[[np.ndarray], bool],
    *,
    timeout: float = DEFAULT_NAV_CONFIG.timeout,
    interval: float = DEFAULT_NAV_CONFIG.interval,
    source: str = '',
    target: str = '',
    candidates: set[str] | None = None,
    probe: bool = False,
    capture_error: bool = True,
    stop_event: threading.Event | None = None,
) -> np.ndarray | None:
    """反复截图，直到 ``checker`` 返回 ``False`` (已离开)。

    目标页面签名未采集时的降级方案。优先使用 :func:`wait_for_page`。

    Parameters
    ----------
    candidates:
        当前页识别的候选页面名集合 (来自 UIStack), 收缩轮询日志中
        全量识别的搜索空间;``None`` 时全量识别。
    probe:
        探测模式 — 超时是**预期结果之一** (如战役次数用尽的出征探测)。
        超时不抛异常、不保存 NavError 截图，返回 ``None`` 交由调用方判定；
        超时日志降为 debug，避免预期分支污染错误记录。
    stop_event:
        任务停止信号 (``ctx.stop_event``)。置位即抛 :class:`TaskStopRequested`，
        即使 ``probe=True`` 也不把它当成「预期超时」吞掉。

    Returns
    -------
    np.ndarray | None
        到达新页面时返回该帧;``probe=True`` 且超时时返回 ``None``。

    Raises
    ------
    NavigationError
        超时仍在原页面 (仅 ``probe=False`` 时)。
    TaskStopRequested
        等待期间 ``stop_event`` 被置位。
    """
    from autowsgr.ui.page import get_current_page

    stage = f'等待离开: {source or "?"} -> {target or "?"}'
    deadline = time.monotonic() + timeout
    attempt = 0
    _log.debug('[UI] 等待离开: {} -> {} (超时 {:.1f}s)', source or '?', target or '?', timeout)

    while True:
        _raise_if_stop_requested(stop_event, stage)
        attempt += 1
        screen = ctrl.screenshot()

        if not checker(screen):
            current = get_current_page(screen, candidates=candidates)
            _log.debug(
                '[UI] 已离开: {} -> {} (第 {} 次截图, 到达={})',
                source or '?',
                target or '?',
                attempt,
                current or '未知',
            )
            return screen

        _log.debug('[UI] 等待离开 #{}: 仍在 {}', attempt, source or '?')

        _raise_if_stop_requested(stop_event, stage)

        if time.monotonic() >= deadline:
            if probe:
                _log.debug(
                    '[UI] 离开超时 (探测): {} -> {} ({} 次截图后仍在 {})',
                    source or '?',
                    target or '?',
                    attempt,
                    source or '?',
                )
                return None
            msg = (
                f'离开超时: {source or "?"} -> {target or "?"}, '
                f'{attempt} 次截图后仍在 {source or "?"}'
            )
            _log.error('[UI] {}', msg)
            raise NavigationError(msg, screen=screen if capture_error else None)

        _sleep_or_stop(stop_event, interval, stage)


# ---------------------------------------------------------------------------
# 带重试的一步导航 - 推荐 API
# ---------------------------------------------------------------------------


def act_and_wait(
    ctrl: AndroidController,
    action: Callable[[], None],
    checker: Callable[[np.ndarray], bool],
    *,
    source: str = '',
    target: str = '',
    config: NavConfig = DEFAULT_NAV_CONFIG,
    candidates: set[str] | None = None,
    stop_event: threading.Event | None = None,
) -> np.ndarray:
    """执行一次动作 → 等待并确认期望结果；未到达则按 ``max_retries`` 重试。

    这是「闭环转移」的统一原语：**动作与期望结果绑定**，而不是点完就走。
    与 :func:`click_and_wait_for_page` 的区别只在于动作可以是任意可调用对象
    （切换舰队、开开关、点面板…），不限于单个坐标点击。

    相比旧实现的三点差别：

    1. **真的重试**。旧 ``click_and_wait_for_page`` 的 docstring 写着「内置重试」，
       实际只点一次、等一次，``NavConfig.max_retries`` / ``retry_delay`` 从未被消费；
    2. **双重确认**。到达判定要求连续 ``config.stable_frames`` 帧匹配，
       挡掉转场渐变里「动画中间态恰好满足 checker」的假到达；
    3. **只在最后一轮留档**。中间轮次的失败不带截图，避免一次导航刷出
       好几张 1.7MB 的 NavError。

    Parameters
    ----------
    stop_event:
        任务停止信号 (``ctx.stop_event``)。每次动作前与等待期间都会检查，
        置位即抛 :class:`TaskStopRequested`；``None`` 时行为与旧版一致。

    Raises
    ------
    NavigationError
        ``max_retries`` 次尝试后仍未到达。
    TaskStopRequested
        动作前或等待期间 ``stop_event`` 被置位。
    """
    stage = f'导航动作: {source or "?"} -> {target or "?"}'
    attempts = max(1, config.max_retries)
    for attempt in range(1, attempts + 1):
        if attempt > 1:
            _log.warning(
                '[UI] 未到达, 重试 {}/{}: {} -> {} (等 {:.1f}s)',
                attempt,
                attempts,
                source or '?',
                target or '?',
                config.retry_delay,
            )
            _sleep_or_stop(stop_event, config.retry_delay, stage)
        _raise_if_stop_requested(stop_event, stage)
        action()
        try:
            return wait_for_page(
                ctrl,
                checker,
                timeout=config.timeout,
                interval=config.interval,
                source=source,
                target=target,
                candidates=candidates,
                stable_frames=config.stable_frames,
                stable_delay=config.stable_delay,
                capture_error=(attempt == attempts),
                stop_event=stop_event,
            )
        except NavigationError:
            if attempt == attempts:
                raise
            # 重试前先复查一次：超时常常只是判定慢，页面其实已经切过去了。
            # 若无脑再点一次，这一击会落在**新页面**上，可能点到别的控件 ——
            # 这比重试本身更危险。
            _raise_if_stop_requested(stop_event, stage)
            settled = ctrl.screenshot()
            if checker(settled):
                _log.info(
                    '[UI] 超时复查已到达, 不再重复动作: {} -> {}', source or '?', target or '?'
                )
                return settled
    raise AssertionError('unreachable')  # pragma: no cover


def click_and_wait_for_page(
    ctrl: AndroidController,
    click_coord: tuple[float, float],
    checker: Callable[[np.ndarray], bool],
    *,
    source: str = '',
    target: str = '',
    config: NavConfig = DEFAULT_NAV_CONFIG,
    candidates: set[str] | None = None,
    stop_event: threading.Event | None = None,
) -> np.ndarray:
    """点击 + 等待到达目标页面，内置重试（见 :func:`act_and_wait`）。

    ``stop_event`` 透传给 :func:`act_and_wait`，等待期间可被用户停止中断。

    Raises
    ------
    NavigationError
        点击后未到达目标页面。
    TaskStopRequested
        点击前或等待期间 ``stop_event`` 被置位。
    """
    return act_and_wait(
        ctrl,
        lambda: ctrl.click(*click_coord),
        checker,
        source=source,
        target=target,
        config=config,
        candidates=candidates,
        stop_event=stop_event,
    )


# ---------------------------------------------------------------------------
# 确认弹窗操作 (Legacy confirm_operation 风格)
# ---------------------------------------------------------------------------


def confirm_operation(
    ctrl: AndroidController,
    *,
    must_confirm: bool = False,
    delay: float = 0.5,
    confidence: float = 0.9,
    timeout: float = 0.0,
) -> bool:
    """等待并点击弹出在屏幕中央的各种确认按钮。

    与 Legacy ``Timer.confirm_operation`` 行为一致:
    在 *timeout* 时限内反复截图寻找任意确认按钮模板，
    找到后精确重定位并点击。

    Parameters
    ----------
    ctrl:
        Android 设备控制器实例。
    must_confirm:
        为 ``True`` 时，超时未找到确认按钮则抛出异常。
    delay:
        点击确认按钮后的睡眠延时 (秒)。
    confidence:
        模板匹配置信度阈值。
    timeout:
        等待确认弹窗出现的最大时限 (秒); <=0 仅检查当前帧。

    Returns
    -------
    bool
        ``True`` 为找到并点击了确认按钮，``False`` 为未找到。

    Raises
    ------
    NavigationError
        *must_confirm* 为 ``True`` 且超时仍未找到确认按钮。
    """
    from autowsgr.image_resources import Templates

    confirm_templates = Templates.Confirm.all()
    deadline = time.monotonic() + max(timeout, 0)

    while True:
        screen = ctrl.screenshot()
        detail = ImageChecker.find_any(
            screen,
            confirm_templates,
            confidence=confidence,
        )
        if detail is not None:
            # 精确重定位 (Legacy 二次匹配风格)
            screen2 = ctrl.screenshot()
            detail2 = ImageChecker.find_any(
                screen2,
                confirm_templates,
                confidence=confidence,
            )
            if detail2 is not None:
                detail = detail2
            ctrl.click(*detail.center)
            _log.info(
                "[UI] 确认操作: 点击 '{}' ({:.4f}, {:.4f})",
                detail.template_name,
                *detail.center,
            )
            time.sleep(delay)
            return True

        if time.monotonic() >= deadline:
            break
        time.sleep(0.3)

    if must_confirm:
        raise NavigationError('确认操作超时: 未找到确认按钮', screen=ctrl.screenshot())
    return False


def click_and_wait_leave_page(
    ctrl: AndroidController,
    click_coord: tuple[float, float],
    checker: Callable[[np.ndarray], bool],
    *,
    source: str = '',
    target: str = '',
    config: NavConfig = DEFAULT_NAV_CONFIG,
    candidates: set[str] | None = None,
    stop_event: threading.Event | None = None,
) -> np.ndarray:
    """点击 + 等待离开当前页面，内置重试。

    目标页面签名未采集时的降级版本。
    优先使用 :func:`click_and_wait_for_page`。

    ``stop_event`` 透传给 :func:`wait_leave_page`，等待期间可被用户停止中断。

    Raises
    ------
    NavigationError
        所有重试均超时。
    TaskStopRequested
        点击前或等待期间 ``stop_event`` 被置位。
    """
    stage = f'离开动作: {source or "?"} -> {target or "?"}'
    last_err: NavigationError | None = None

    for attempt in range(1, config.max_retries + 1):
        if attempt > 1:
            _log.warning(
                '[UI] 离开重试 {}/{}: {} -> {} (等 {:.1f}s)',
                attempt,
                config.max_retries,
                source or '?',
                target or '?',
                config.retry_delay,
            )
            _sleep_or_stop(stop_event, config.retry_delay, stage)

        _raise_if_stop_requested(stop_event, stage)
        ctrl.click(*click_coord)

        try:
            return wait_leave_page(
                ctrl,
                checker,
                timeout=config.timeout,
                interval=config.interval,
                source=source,
                target=target,
                candidates=candidates,
                capture_error=(attempt == config.max_retries),
                stop_event=stop_event,
            )
        except NavigationError as e:
            last_err = e
            _log.warning(
                '[UI] 点击后离开超时 ({}/{}): {} -> {}',
                attempt,
                config.max_retries,
                source or '?',
                target or '?',
            )

    raise NavigationError(
        f'离开失败 (已重试 {config.max_retries} 次): {source or "?"} -> {target or "?"}',
        screen=ctrl.screenshot(),
    ) from last_err
